<!doctype html><html lang="bn"><head>@include('bn_font')<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#0f1b3d"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="mobile-web-app-capable" content="yes"><title>Staff App</title>
<style>
:root{--n:#0f1b3d;--o:#f26b1d;--g:#f4f5f8;--b:#e3e6ee;--t:#1b2238;--m:#6b7390}*{box-sizing:border-box}body{margin:0;font:15px/1.4 Inter,Bornomala,sans-serif;background:var(--g);color:var(--t);padding-bottom:70px}
header{background:var(--n);color:#fff;padding:12px 16px;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:5}header b{font-size:17px}header button{background:none;border:0;color:#fff;font-size:20px}
main{padding:12px;max-width:640px;margin:auto}.card{background:#fff;border:1px solid var(--b);border-radius:12px;padding:12px;margin-bottom:10px}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.st{background:#fff;border:1px solid var(--b);border-radius:12px;padding:10px 12px}.st b{display:block;font-size:22px;color:var(--n)}.st span{font-size:12px;color:var(--m)}
nav{position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:1px solid var(--b);display:flex;padding-bottom:env(safe-area-inset-bottom)}nav button{flex:1;border:0;background:none;padding:10px 0;font-size:12px;color:var(--m)}nav button.on{color:var(--o);font-weight:700}nav i{display:block;font-style:normal;font-size:20px}
input,select,textarea{width:100%;padding:12px;border:1px solid var(--b);border-radius:10px;font:inherit;background:#fff}.btn{background:var(--o);color:#fff;border:0;border-radius:10px;padding:13px;font-weight:700;width:100%;font-size:15px}.btn.s{background:var(--n)}
.pills{display:flex;gap:6px;overflow-x:auto;margin-bottom:10px;padding-bottom:4px}.pills button{white-space:nowrap;border:1px solid var(--b);background:#fff;border-radius:20px;padding:7px 12px;font-size:13px}.pills button.on{background:var(--n);color:#fff;border-color:var(--n)}
.row{display:flex;justify-content:space-between;gap:8px;align-items:center}.m{color:var(--m);font-size:12.5px}.tag{display:inline-block;background:#eef0f6;border-radius:6px;padding:2px 7px;font-size:12px;margin-right:4px}.tag.ai{background:#e6f6ec;color:#18794e}.tag.mn{background:#fff1e6;color:#b4560f}
.msg{max-width:82%;padding:8px 11px;border-radius:12px;margin:4px 0;white-space:pre-wrap;word-break:break-word}.in{background:#fff;border:1px solid var(--b)}.out{background:#dcf2e4;margin-left:auto}.err{color:#c0392b;font-size:11px}
.pc{display:inline-block;width:120px;margin:4px 6px 0 0;vertical-align:top}.pc img{width:120px;height:120px;object-fit:cover;border-radius:8px}.pc div{font-size:12px}
nav b.bd{position:absolute;margin:-6px 0 0 8px;background:var(--o);color:#fff;border-radius:10px;padding:0 6px;font-size:11px;line-height:16px}nav button{position:relative}.mic{background:#fff;border:2px solid var(--o);color:var(--o);border-radius:50%;width:54px;height:54px;font-size:24px;flex:none}.mic.rec{background:#d93025;border-color:#d93025;color:#fff;animation:pl 1s infinite}@keyframes pl{50%{opacity:.6}}.lg{display:flex;gap:6px;margin-top:6px}.lg button{flex:1;border:1px solid var(--b);background:#fff;border-radius:8px;padding:7px;font-size:13px}.lg button.on{background:var(--n);color:#fff}#toast{position:fixed;top:60px;left:50%;transform:translateX(-50%);background:#222;color:#fff;padding:9px 14px;border-radius:20px;font-size:13px;display:none;z-index:9}a{color:var(--o)}
</style></head><body>
<header><b id="ttl">Staff App</b><button id="bk" style="display:none">←</button><button id="lo" style="display:none" title="Logout">⎋</button></header>
<main id="v"></main><nav id="nv" style="display:none"></nav><div id="toast"></div>
@verbatim
<script>
const $=s=>document.querySelector(s),API='/api/staff';let T=null,ME=null,tab='dash',stack=[],timer=null,DID;
try{T=localStorage.getItem('st');DID=localStorage.getItem('did')||(Math.random().toString(36).slice(2)+Date.now().toString(36));localStorage.setItem('did',DID)}catch(e){DID='web'+Date.now()}
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function toast(m){const t=$('#toast');t.textContent=m;t.style.display='block';setTimeout(()=>t.style.display='none',2600)}
async function api(p,o={}){const r=await fetch(API+p,{method:o.m||'GET',headers:{'Accept':'application/json','Content-Type':'application/json',...(T?{Authorization:'Bearer '+T}:{})},body:o.b?JSON.stringify(o.b):undefined});if(r.status==401&&T){out();throw 0}const j=await r.json().catch(()=>({}));if(!r.ok)throw j;return j}
function out(){T=null;try{localStorage.removeItem('st')}catch(e){}login()}
function login(){clear();$('#nv').style.display='none';$('#lo').style.display='none';$('#bk').style.display='none';$('#ttl').textContent='Mother Commerce Staff';
$('#v').innerHTML='<div class="card"><p class="m">Staff login</p><p><input id="l" placeholder="Email বা মোবাইল" autocomplete="username"></p><p><input id="p" type="password" placeholder="Password" autocomplete="current-password"></p><button class="btn" id="go">Login</button></div>';
$('#go').onclick=async()=>{try{const j=await api('/login',{m:'POST',b:{login:$('#l').value,password:$('#p').value,device_id:DID,device_name:navigator.userAgent.slice(0,100),platform:/iPhone|iPad/.test(navigator.userAgent)?'ios':'android',app_version:'web-1'}});T=j.token;ME=j.user;try{localStorage.setItem('st',T)}catch(e){}start()}catch(e){toast(e.message||'Login failed')}}}
function clear(){clearInterval(timer);timer=null}
function shell(){$('#nv').style.display='flex';$('#lo').style.display='block';$('#nv').innerHTML=[['dash','◉','Dashboard'],['ord','▤','Orders'],['msg','✉','Messages'],['task','✓','Tasks'],['more','⋯','More']].map(x=>`<button class="${tab==x[0]?'on':''}" data-t="${x[0]}"><i>${x[1]}</i>${x[2]}${BD[x[0]]?`<b class="bd">${BD[x[0]]}</b>`:''}</button>`).join('');document.querySelectorAll('#nv button').forEach(b=>b.onclick=()=>{tab=b.dataset.t;stack=[];route()})}
function back(){stack.pop();route()}
$('#bk').onclick=back;$('#lo').onclick=async()=>{try{await api('/logout',{m:'POST'})}catch(e){}out()};
async function start(){try{if(!ME)ME=(await api('/me')).user}catch(e){return}shell();route();badges();setInterval(()=>T&&badges(),20000)}
function route(){clear();shell();const top=stack[stack.length-1];$('#bk').style.display=top?'block':'none';if(top){return top.t=='order'?order(top.id):top.t=='thread'?thread(top.id):0}({dash,ord:orders,msg:msgs,task:tasks,more}[tab])()}
async function dash(){$('#ttl').textContent='Dashboard';const load=async()=>{try{const d=await api('/dashboard'),o=d.orders,s=(n,v,f)=>`<div class="st" ${f?`data-f="${f}"`:''}><b>${v??'—'}</b><span>${n}</span></div>`;$('#v').innerHTML='<div class="grid">'+s('Pending',o.pending,'Pending')+s('AI Approved',o.ai_approved)+s('Manual Approved',o.manual_approved)+s('Packaging',o.packaging,'Packaging')+s('Shipment',o.shipment,'Shipment')+s('Delivered Today',o.delivered_today)+s('Late Delivery',o.late_delivery,'Late Delivery')+s('Returns',o.returns,'Returned')+s('Unread Messages',d.messages.unread)+s('Assigned to me',d.messages.assigned_to_me)+s('My Tasks',d.tasks.open_mine)+s('Low Stock',d.low_stock)+'</div>';document.querySelectorAll('[data-f]').forEach(e=>e.onclick=()=>{OF=e.dataset.f;tab='ord';route()})}catch(e){if(e)$('#v').innerHTML='<div class="card">'+esc(e.message||'Error')+'</div>'}};load();timer=setInterval(load,30000)}
let BD={};async function badges(){try{const d=await api('/dashboard');BD={ord:d.orders.pending,msg:d.messages.unread,task:d.tasks.open_mine};document.querySelectorAll('#nv button').forEach(b=>{const k=b.dataset.t;b.querySelector('.bd')?.remove();if(BD[k])b.insertAdjacentHTML('beforeend','<b class="bd">'+BD[k]+'</b>')})}catch(e){}}
let OF='Pending',OQ='';
const ST=['Pending','Approved','Packaging','Shipment','Delivered','Late Delivery','Returned','Cancel'];
async function orders(){$('#ttl').textContent='Orders';$('#v').innerHTML='<input id="q" placeholder="Invoice / মোবাইল / নাম / ট্র্যাকিং" value="'+esc(OQ)+'"><div class="pills" style="margin-top:10px">'+['All',...ST].map(s=>`<button class="${(OF||'All')==s?'on':''}" data-s="${s}">${s}</button>`).join('')+'</div><div id="ol"></div>';
document.querySelectorAll('.pills button').forEach(b=>b.onclick=()=>{OF=b.dataset.s=='All'?'':b.dataset.s;orders()});let dt;$('#q').oninput=e=>{OQ=e.target.value;clearTimeout(dt);dt=setTimeout(list,400)};let cur=null;
async function list(more){try{const j=await api('/orders?status='+encodeURIComponent(OF)+'&q='+encodeURIComponent(OQ)+(more&&cur?'&cursor='+cur:''));cur=j.next_cursor;const h=j.orders.map(o=>`<div class="card" data-id="${o.id}"><div class="row"><b>${esc(o.invoice)}</b><b>৳${Math.round(o.total)}</b></div><div>${esc(o.customer)} · ${esc(o.phone)}</div><div class="m">${esc(o.status)} · ${esc(o.created_at)}${o.store?' · '+esc(o.store):''}</div><div style="margin-top:4px">${o.approval?`<span class="tag ${/AI/.test(o.approval)?'ai':'mn'}">${esc(o.approval)}</span>`:''}${o.courier?`<span class="tag">${esc(o.courier)}</span>`:''}${o.payment?`<span class="tag">${esc(o.payment)}</span>`:''}</div></div>`).join('')||'<p class="m">কিছু নেই</p>';const l=$('#ol');if(more)l.querySelector('#mr')?.remove();l.insertAdjacentHTML(more?'beforeend':'afterbegin',(more?'':'')+h+(cur?'<button class="btn s" id="mr">আরও</button>':''));if(!more)l.innerHTML=h+(cur?'<button class="btn s" id="mr">আরও</button>':'');l.querySelectorAll('.card').forEach(c=>c.onclick=()=>{stack.push({t:'order',id:c.dataset.id});route()});$('#mr')&&($('#mr').onclick=()=>list(true))}catch(e){if(e)toast(e.message||'Error')}}list()}
async function order(id){$('#ttl').textContent='Order';try{const o=(await api('/orders/'+id)).order,cs=o.customer_stats;$('#v').innerHTML=`<div class="card"><div class="row"><b>${esc(o.invoice)}</b><b>৳${Math.round(o.total)}</b></div><div>${esc(o.customer)}</div><div class="row"><a href="tel:${esc(o.phone)}">📞 ${esc(o.phone)}</a><a href="https://wa.me/88${esc(o.phone.replace(/^\+?88/,''))}">WhatsApp</a></div><div class="m">${esc(o.address||'')} ${esc(o.district||'')}</div><div style="margin-top:6px"><span class="tag">${esc(o.status)}</span>${o.approval?`<span class="tag ${/AI/.test(o.approval)?'ai':'mn'}">${esc(o.approval)}</span>`:''}${o.store?`<span class="tag">${esc(o.store)}</span>`:''}<span class="tag">${esc(o.source||'')}</span></div></div>
<div class="card"><b>Products</b>${o.items.map(i=>`<div class="row" style="margin-top:6px"><span>${esc(i.name)} × ${i.qty}</span><span>৳${Math.round(i.price*i.qty)}</span></div>`).join('')}<div class="m" style="margin-top:6px">Shipping ৳${Math.round(o.shipping)} · Discount ৳${Math.round(o.discount)}${o.payment?' · '+esc(o.payment):''}</div>${o.note?`<div class="m">Note: ${esc(o.note)}</div>`:''}</div>
<div class="card"><b>Customer</b><div class="m">Orders ${cs.total_orders} · Delivered ${cs.delivered} · Returned ${cs.returned} · Cancelled ${cs.cancelled}${cs.success_rate!=null?' · Success '+cs.success_rate+'%':''} · Spent ৳${Math.round(cs.spent)}</div></div>
<div class="card"><b>Status বদলান</b><p><select id="ns">${o.next_statuses.map(s=>`<option ${s==o.status?'selected':''}>${s}</option>`).join('')}</select></p><p><input id="nn" placeholder="Note (ঐচ্ছিক)"></p><button class="btn" id="sv">Update</button></div>
${o.courier||o.tracking?`<div class="card"><b>Courier</b><div>${esc(o.courier||'')} ${esc(o.tracking||'')}</div><div class="m">${esc(o.courier_status||'')}</div></div>`:''}
<div class="card"><b>Timeline</b>${o.timeline.map(l=>`<div class="m" style="margin-top:4px">${esc(l.at)} · ${esc(l.by||'System')}: ${esc(l.from||'')} → <b>${esc(l.to)}</b> ${esc(l.note||'')}</div>`).join('')}</div>`;
$('#sv').onclick=async()=>{const s=$('#ns').value;if(s==o.status)return toast('একই স্ট্যাটাস');if(['Cancel','Returned','Return Pending'].includes(s)&&!confirm(s+' করবেন?'))return;try{const j=await api('/orders/'+id+'/status',{m:'POST',b:{status:s,note:$('#nn').value}});toast(j.message||(j.success===false?'হয়নি':'আপডেট হয়েছে'));if(j.success!==false)order(id)}catch(e){toast(e.message||'Error')}}}catch(e){if(e)$('#v').innerHTML='<div class="card">'+esc(e.message||'Error')+'</div>'}}
let MF='unread';
async function msgs(){$('#ttl').textContent='Messages';const F=[['unread','Unread'],['all','All'],['assigned','Mine'],['whatsapp','WhatsApp'],['facebook','Facebook'],['instagram','Instagram'],['web','Web'],['resolved','Resolved']];
$('#v').innerHTML='<div class="pills">'+F.map(f=>`<button class="${MF==f[0]?'on':''}" data-f="${f[0]}">${f[1]}</button>`).join('')+'</div><div id="tl"></div>';document.querySelectorAll('.pills button').forEach(b=>b.onclick=()=>{MF=b.dataset.f;msgs()});
const load=async()=>{try{const j=await api('/chat/threads?f='+MF);$('#tl').innerHTML=j.threads.map(t=>`<div class="card" data-id="${t.id}"><div class="row"><b>${esc(t.name||t.phone||t.username||'Customer')}</b>${t.unread?`<span class="tag mn">${t.unread}</span>`:''}</div><div class="m">${esc(t.channel_name)}${t.source?' · '+esc(t.source):''}${t.assigned_name?' · '+esc(t.assigned_name):''}</div><div style="margin-top:3px">${esc((t.last||'').slice(0,90))}</div></div>`).join('')||'<p class="m">কোনো মেসেজ নেই</p>';document.querySelectorAll('#tl .card').forEach(c=>c.onclick=()=>{stack.push({t:'thread',id:c.dataset.id});route()})}catch(e){if(e)toast(e.message||'Error')}};load();timer=setInterval(load,12000)}
function voice(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition,mc=$('#mc');let lang='bn-BD',rg=null,on=false;document.querySelectorAll('.lg button').forEach(b=>b.onclick=()=>{lang=b.dataset.l;document.querySelectorAll('.lg button').forEach(x=>x.classList.toggle('on',x==b));if(on)rg&&rg.stop()});
if(!SR){mc.onclick=()=>toast('এই ব্রাউজারে ভয়েস টাইপ নেই। Chrome ব্যবহার করুন, অথবা কিবোর্ডের 🎤 চাপুন।');return}
function go(){const ta=$('#rb'),base=ta.value?ta.value.trim()+' ':'';const r=new SR();rg=r;r.lang=lang;r.continuous=true;r.interimResults=true;let fin='';
r.onresult=e=>{let it='';for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript;if(e.results[i].isFinal)fin+=t+' ';else it+=t}ta.value=base+fin+it};
r.onerror=e=>{if(e.error==='not-allowed'||e.error==='service-not-allowed'){on=false;toast('মাইক্রোফোনের অনুমতি দিন (ব্রাউজারের তালা আইকন → Microphone → Allow)')}else if(e.error==='language-not-supported'&&lang==='bn-BD'){lang='bn-IN'}else if(e.error==='no-speech'){}else toast('ভয়েস সমস্যা: '+e.error)};
r.onend=()=>{if(on)try{go()}catch(x){on=false}else{mc.classList.remove('rec');mc.textContent='🎤'}};try{r.start();mc.classList.add('rec');mc.textContent='■'}catch(x){on=false}}
mc.onclick=()=>{if(on){on=false;rg&&rg.stop()}else{on=true;go()}}}
async function thread(id){$('#ttl').textContent='Chat';let tok=0;const load=async(scroll)=>{try{const j=await api('/chat/thread/'+id),t=j.thread;$('#ttl').textContent=t.name||t.phone||'Chat';const box=$('#mb'),keep=!box||box.scrollHeight-box.scrollTop-box.clientHeight<80;const h=j.messages.map(m=>`<div class="msg ${m.dir=='in'?'in':'out'}">${esc(m.body||'')}${m.att&&m.att_type=='image'?`<br><img src="${esc(m.att)}" style="max-width:100%;border-radius:8px">`:''}${(m.cards||[]).length?'<div>'+m.cards.map(c=>`<a class="pc" href="${esc(c.url)}" target="_blank"><img src="${esc(c.image||'')}"><div>${esc(c.name)}</div><div>৳${esc(c.price)}</div></a>`).join('')+'</div>':''}<div class="m">${m.dir=='out'?esc(m.by||(m.is_ai?'AI':''))+' · ':''}${esc(new Date(m.at).toLocaleTimeString('bn-BD',{hour:'2-digit',minute:'2-digit'}))}</div>${m.status=='failed'?`<div class="err">পাঠানো যায়নি: ${esc(m.error||'')}</div>`:''}</div>`).join('');
if(!$('#mb')){$('#v').innerHTML=`<div class="m" id="hd"></div><div id="mb" style="min-height:50vh"></div><div style="position:sticky;bottom:64px;background:var(--g);padding:6px 0"><textarea id="rb" rows="2" placeholder="রিপ্লাই লিখুন..."></textarea><div class="lg"><button data-l="bn-BD" class="on">বাংলা</button><button data-l="en-US">English</button></div><div style="display:flex;gap:8px;margin-top:6px;align-items:center"><button class="mic" id="mc" type="button" title="বলুন, লিখে দেব">🎤</button><button class="btn s" id="ai" style="flex:1">AI সাজেশন</button><button class="btn" id="sd" style="flex:1">পাঠান</button></div></div>`;$('#sd').onclick=send;$('#ai').onclick=aiHint;voice()}$('#hd').innerHTML=`${esc(t.channel_name)}${t.source?' · '+esc(t.source):''} · ${esc(t.phone||'')} ${t.phone?`<a href="tel:${esc(t.phone)}">📞</a>`:''} · Orders ${t.orders}`;$('#mb').innerHTML=h;if(keep||scroll)window.scrollTo(0,document.body.scrollHeight)}catch(e){if(e)toast(e.message||'Error')}};
async function send(){const b=$('#rb').value.trim();if(!b)return;$('#sd').disabled=true;try{const j=await api('/chat/thread/'+id+'/reply',{m:'POST',b:{body:b,kind:'text',client_token:'a'+Date.now()}});if(j.error)toast('সমস্যা: '+j.error);else{$('#rb').value='';toast('পাঠানো হয়েছে')}await load(true)}catch(e){toast((e&&(e.message||e.error))||'Error')}$('#sd').disabled=false}
async function aiHint(){$('#ai').disabled=true;try{const j=await api('/chat/thread/'+id),h=j.hint,s=typeof h==='string'?h:(h&&(h.reply||h.text||h.draft))||'';if(s)$('#rb').value=s;else toast('এখনো কোনো AI সাজেশন নেই')}catch(e){toast((e&&e.message)||'Error')}$('#ai').disabled=false}
await load(true);timer=setInterval(()=>load(false),8000)}
async function tasks(){$('#ttl').textContent='Tasks';try{const j=await api('/tasks');$('#v').innerHTML='<button class="btn s" id="nt" style="margin-bottom:10px">+ নতুন টাস্ক</button>'+(j.tasks.map(t=>`<div class="card"><div class="row"><b>${esc(t.title)}</b><span class="tag">${esc(t.priority)}</span></div><div class="m">${esc(t.status)}${t.due_at?' · Due '+esc(t.due_at):''}</div><div style="margin-top:6px"><button class="pills" data-i="${t.id}" data-s="in_progress" style="all:unset;color:var(--o)">Start</button> · <button data-i="${t.id}" data-s="done" style="all:unset;color:#18794e">Done ✓</button></div></div>`).join('')||'<p class="m">কোনো টাস্ক নেই</p>');document.querySelectorAll('[data-i]').forEach(b=>b.onclick=async()=>{await api('/tasks/'+b.dataset.i,{m:'POST',b:{status:b.dataset.s}});tasks()});$('#nt').onclick=async()=>{const t=prompt('টাস্কের নাম');if(!t)return;await api('/tasks',{m:'POST',b:{title:t}});tasks()}}catch(e){if(e)toast(e.message||'Error')}}
async function more(){$('#ttl').textContent='More';$('#v').innerHTML=`<div class="card"><b>${esc(ME.name)}</b><div class="m">${esc(ME.role)} · ${esc(ME.email||'')}</div></div><div class="card"><b>Devices</b><div id="dv" class="m">লোড হচ্ছে…</div></div><button class="btn s" id="lg">Logout</button>`;$('#lg').onclick=$('#lo').onclick;try{const j=await api('/devices');$('#dv').innerHTML=j.devices.map(d=>`<div class="row" style="margin-top:6px"><span>${esc((d.device_name||'').slice(0,40))}${d.current?' (এই ডিভাইস)':''}<br><span class="m">${esc(d.last_used||'')}</span></span>${d.current?'':`<button data-r="${d.id}" style="border:1px solid var(--b);background:#fff;border-radius:8px;padding:6px 10px">Remove</button>`}</div>`).join('');document.querySelectorAll('[data-r]').forEach(b=>b.onclick=async()=>{await api('/devices/'+b.dataset.r+'/revoke',{m:'POST'});more()})}catch(e){}}
T?start():login();
</script>
@endverbatim
</body></html>
